// ---------------------------------------------------------------- js/device-profile.js
/**
 * DeviceProfile — 设备自适应渲染参数
 *
 * 根据是否存在高精度指针（鼠标 / 触控板 / 数位笔）分流：
 *   fine = true  → 桌面 / iPad+Pencil      → 放开性能
 *   fine = false → 纯触控平板 / 手机        → 保守，省 fillrate
 *
 * `any-pointer: fine` 判据比 UA 检测稳：iPad Pro + Pencil 被归为桌面级，
 * 只有手指触控的平板才走触控配置。
 */
(function(global) {
    const hasFinePointer = typeof matchMedia === 'function'
        && matchMedia('(any-pointer: fine)').matches;

    // iPad 识别：原生 UA 或伪装 Mac（"请求桌面网站"模式下 platform=MacIntel，
    // 但 maxTouchPoints>1 暴露真身；真 Mac 触控板 maxTouchPoints 为 0/1）
    const ua = (typeof navigator !== 'undefined' && navigator.userAgent) || '';
    const isIPad = /iPad/.test(ua) ||
        (typeof navigator !== 'undefined'
            && navigator.platform === 'MacIntel'
            && (navigator.maxTouchPoints || 0) > 1);

    // drip（湿区往下流动）启动期硬门槛：
    //   - 屏幕宽 < 600px：直接关，省得测（手机端笔触短，效果几乎不可见）
    //   - hardwareConcurrency < 4：低端设备不开
    // 通过门槛 ≠ 一定开启，用户手动开关可覆盖。
    const screenW = (typeof window !== 'undefined' && window.screen) ? window.screen.width : 1024;
    const cores = (typeof navigator !== 'undefined' && navigator.hardwareConcurrency) || 4;
    const dripPassesScreen = screenW >= 600;
    const dripPassesCores = cores >= 4;

    const DeviceProfile = {
        hasFinePointer,
        isIPad,

        // 目标帧率：桌面 100Hz（高刷屏也只限到 100），触控 60Hz
        TARGET_FPS: hasFinePointer ? 100 : 60,

        // 水彩扩散/颜色 GPU pass 批处理步长（N 帧合并一次）
        WET_PASS_STRIDE: hasFinePointer ? 1 : 2,

        // scheduler 单帧 drawBrush 次数上限
        // iPad（含 Pencil 伪装桌面）：单帧 drawBrush 超 6 次容易超 16ms 预算 → 卡顿
        // 桌面：保持高上限（CPU 强，极少触发）
        // 纯触控：保守兜底
        MAX_STEPS_PER_FRAME: isIPad ? 15 : hasFinePointer ? 120 : 15,

        // drip 启动期允许加载（仍可被用户手动开关覆盖）
        DRIP_ENABLED: dripPassesScreen && dripPassesCores,

        // drip 传播 pass 节流：触控设备每 N 帧才跑一次传播，省 fillrate
        DRIP_PASS_STRIDE: hasFinePointer ? 1 : 3,
    };

    global.DeviceProfile = DeviceProfile;
})(window);


// ---------------------------------------------------------------- js/frame-scheduler.js
/**
 * Frame Scheduler — 统一渲染循环
 *
 * 把分散的持续性 RAF 循环（热度衰减、水彩沉积、pointermove 绘制等）
 * 合并到单一 RAF tick，按优先级顺序执行。
 *
 * 用法：
 *   FrameScheduler.register('heatmap-fade', (dt) => {...}, 40);
 *   FrameScheduler.setActive('heatmap-fade', false);   // 暂停但保留注册
 *   FrameScheduler.unregister('heatmap-fade');         // 彻底移除
 *
 * 优先级约定（数字越小越先执行）：
 *   10  stroke-draw       pointermove 合批绘制
 *   20  wet-diffusion     水彩扩散
 *   30  deposit-color     松笔沉积
 *   40  heatmap-fade      热度衰减
 *   50  默认
 *
 * dt 参数单位 ms；首帧为 0。
 */
(function(global) {
    const tasks = new Map();   // name -> { fn, priority, active }
    let sortedCache = null;    // 按 priority 排序的数组，tasks 变动时失效
    let rafId = 0;
    let lastTick = 0;
    // 初始值从 DeviceProfile 读取（桌面 100 / 触控 60）；后续可 setTargetFPS 覆盖
    const _initialFps = (typeof DeviceProfile !== 'undefined' && DeviceProfile.TARGET_FPS) || 60;
    let targetFps = _initialFps;
    let minFrameMs = (1000 / targetFps) * 0.9;    // 留 10% 缓冲，避免 RAF 抖动导致掉帧

    function _invalidateSort() { sortedCache = null; }

    function _sorted() {
        if (!sortedCache) {
            sortedCache = [...tasks.values()].sort((a, b) => a.priority - b.priority);
        }
        return sortedCache;
    }

    function _hasActive() {
        for (const t of tasks.values()) if (t.active) return true;
        return false;
    }

    function _tick(now) {
        // 节流：帧间隔未到目标最小值就跳过这一轮（不更新 lastTick，等下一帧再判断）
        if (targetFps > 0 && lastTick && (now - lastTick) < minFrameMs) {
            rafId = requestAnimationFrame(_tick);
            return;
        }

        const dt = lastTick ? (now - lastTick) : 0;
        lastTick = now;

        for (const t of _sorted()) {
            if (!t.active) continue;
            try {
                t.fn(dt);
            } catch (e) {
                console.error('[FrameScheduler]', t.name, 'threw:', e);
            }
        }

        if (_hasActive()) {
            rafId = requestAnimationFrame(_tick);
        } else {
            rafId = 0;
            lastTick = 0;
        }
    }

    function _ensureRunning() {
        if (!rafId) {
            lastTick = 0;
            rafId = requestAnimationFrame(_tick);
        }
    }

    const FrameScheduler = {
        register(name, fn, priority = 50) {
            if (typeof fn !== 'function') throw new Error('[FrameScheduler] fn must be function');
            tasks.set(name, { name, fn, priority, active: true });
            _invalidateSort();
            _ensureRunning();
        },

        unregister(name) {
            if (tasks.delete(name)) _invalidateSort();
        },

        setActive(name, active) {
            const t = tasks.get(name);
            if (!t) return;
            t.active = !!active;
            if (t.active) _ensureRunning();
        },

        has(name) { return tasks.has(name); },

        /**
         * 设置目标帧率。0 表示不限制（跟随原生 RAF，通常 60/120Hz）。
         * 设备屏幕 > 目标 fps 时会跳过中间帧，节省 GPU 开销。
         */
        setTargetFPS(fps) {
            targetFps = Math.max(0, fps | 0);
            minFrameMs = targetFps > 0 ? (1000 / targetFps) * 0.9 : 0;
        },

        getTargetFPS() { return targetFps; },

        // 调试用
        _list() {
            return [...tasks.values()].map(t => ({ name: t.name, priority: t.priority, active: t.active }));
        }
    };

    global.FrameScheduler = FrameScheduler;
})(window);


// ---------------------------------------------------------------- js/base-painter.js
// 所有渲染参数常数见 js/params.js

/**
 * BaseWebGLPainter — 共享 WebGL 基类
 *
 * 包含：
 *  - 所有两个引擎共用的 WebGL 基础设施
 *  - GPU 纹理历史记录池（撤销/重做零 readPixels）
 *  - requestIdleCallback 异步 CPU 备份 + localStorage 写入
 *
 * 子类须实现：
 *  _buildFragmentShader()   → 返回片段着色器字符串
 *  _getExtraUniformNames()  → 返回额外 uniform 名数组
 *  async _loadLUT()         → 加载 LUT 纹理到 this.textures.lut
 *  _bindLUT()               → drawBrush 时绑定 LUT 到正确纹理槽
 */
let _painterInstanceSeq = 0;

class BaseWebGLPainter {
    constructor(canvas) {
        this._instanceId = ++_painterInstanceSeq;
        this.canvas = canvas;
        this.gl = null;

        this.program = null;
        this.textures = {};
        this.framebuffers = {};
        this.buffers = {};
        this.locations = {};
        this.currentBrushTexture = null;

        this.baseMixStrength = DEFAULT_MIX_STRENGTH;

        // GPU 历史池
        this._history = [];          // HistoryFrame[]
        this._historyStep = -1;      // 当前指针
        this._frameCounter = 0;      // 单调递增帧 ID
        this._maxGpuSlots = GPU_SLOTS_MAX;  // init 后由 _calcGpuBudget 设定
        this._gpuFreeSlots = [];     // 可用 GPU slot 对象 { tex, fb }
        this._engineBirthTime = performance.now();

        // blit 程序（用于历史帧还原）
        this._blitProgram = null;
        this._blitLocations = {};
        this._blitBuffer = null;

        // 待处理的 idle 任务 Map<frameId, handle>
        this._pendingIdle = new Map();

        // 笔画状态闸门：连续绘制时暂停 idle 备份，避免与笔画帧挤占主线程
        this._strokeActive = false;
        this._quietDelayHandle = null;  // setTimeout handle，静默到期触发真正 rIC
        this._backupDeferred = false;   // 有帧等着备份但被闸门挡住，静默到期需要 flush

        // 历史压缩 Worker（惰性创建）
        this._historyWorker = null;
        this._workerMsgId = 0;
        this._workerPending = new Map();   // msgId → { resolve, reject }
        this._decompressCache = new Map(); // frameId → Uint8ClampedArray（LRU 简版）
        this._decompressCacheMax = 3;
        this._lastRestoreDir = 0;          // +1 redo, -1 undo, 0 未知
        this._lastRestoreStep = -1;
        this._restoreSeq = 0;              // 异步 restore 令牌，防止乱序解压结果覆盖正确帧

        // drawBrush 每帧复用的顶点位置缓冲，避免频繁分配引发 GC
        this._quadPos = new Float32Array(8);

        // 湿度相关 uniform 缓存：仅在 setWetness 时重算
        this._wetCache = null;
        this._recomputeWetCache(0.5);
    }

    _recomputeWetCache(w) {
        this._wetCache = {
            bleedMix:    WET_BLEED_MIX    * (WET_BLEED_SCALE_MIN  + (WET_BLEED_SCALE_MAX  - WET_BLEED_SCALE_MIN)  * w),
            bleedRadius: WET_BLEED_RADIUS * (WET_BLEED_SCALE_MIN  + (WET_BLEED_SCALE_MAX  - WET_BLEED_SCALE_MIN)  * w),
            // coldMix 仅 mixbox-painter 使用；KM 已移除该乘数。湿度调制去掉，统一为恒定 WET_COLD_MIX。
            coldMix:     WET_COLD_MIX,
            smudgeMix:   WET_SMUDGE_MIX   * (WET_SMUDGE_SCALE_MIN + (WET_SMUDGE_SCALE_MAX - WET_SMUDGE_SCALE_MIN) * w),
        };
    }

    // ─────────────────────────────────────────────
    // 抽象接口（子类实现）
    // ─────────────────────────────────────────────

    /** 返回片段着色器 GLSL 字符串 */
    _buildFragmentShader() { throw new Error('BaseWebGLPainter: _buildFragmentShader() not implemented'); }

    /** 返回需要额外获取 location 的 uniform 名数组，如 ['mixbox_lut'] */
    _getExtraUniformNames() { return []; }

    /** 加载 LUT 纹理（可为异步），完成后写入 this.textures.lut */
    async _loadLUT() {}

    /** 在 drawBrush 里绑定 LUT 到正确纹理槽 */
    _bindLUT() {}

    // ─────────────────────────────────────────────
    // 初始化模板方法
    // ─────────────────────────────────────────────

    async init() {
        this.initWebGL();
        this._calcGpuBudget();
        this.compileShaders();
        await this._loadLUT();
        this._initDripCapable();
        this.setupTextures();
        this.setupFramebuffers();
        this.setupGeometry();
        this._initBlitProgram();
        this._initHeatmapProgram();
        this._initHeatDecayProgram();
        this._initWetPaperProgram();
    }

    initWebGL() {
        this.gl = this.canvas.getContext('webgl2', {
            alpha: false,
            premultipliedAlpha: false,
            preserveDrawingBuffer: true,
        });

        if (!this.gl) throw new Error('WebGL2 不支持');

        const gl = this.gl;
        gl.disable(gl.BLEND);
        gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
    }

    // ─────────────────────────────────────────────
    // GPU 预算计算
    // ─────────────────────────────────────────────

    _calcGpuBudget(budgetMB = GPU_BUDGET_MB) {
        this._gpuBudgetMB = budgetMB;
        const bytesPerFrame = this.canvas.width * this.canvas.height * 4;
        const budgetBytes = (budgetMB - GPU_RUNTIME_OVERHEAD_MB) * 1024 * 1024;
        this._maxGpuSlots = Math.min(GPU_SLOTS_MAX, Math.max(GPU_SLOTS_MIN, Math.floor(budgetBytes / bytesPerFrame)));
    }

    // ─────────────────────────────────────────────
    // 着色器
    // ─────────────────────────────────────────────

    compileShaders() {
        const gl = this.gl;

        // 主 program 按引擎子类缓存：每个引擎 shader 只编译一次，后续切换复用。
        const cacheKey = this.constructor.name;
        const cached = BaseWebGLPainter._programCache.main.get(cacheKey);
        if (cached) {
            this.program = cached.program;
            this.locations = cached.locations;
            return;
        }

        const vsSource = `#version 300 es
        in vec2 a_position;
        in vec2 a_texCoord;

        out vec2 v_texCoord;
        out vec2 v_canvasCoord;

        uniform vec2 u_resolution;
        uniform float u_smudgeAlpha;

        void main() {
            vec2 clipSpace = (a_position / u_resolution) * 2.0 - 1.0;
            gl_Position = vec4(clipSpace * vec2(1, -1), 0, 1);
            v_texCoord = a_texCoord;
            v_canvasCoord = a_position;
        }
        `;

        const fsSource = this._buildFragmentShader();

        const vs = this.createShader(gl.VERTEX_SHADER, vsSource);
        const fs = this.createShader(gl.FRAGMENT_SHADER, fsSource);
        this.program = this.createProgram(vs, fs);

        this.locations = {
            a_position:        gl.getAttribLocation(this.program, 'a_position'),
            a_texCoord:        gl.getAttribLocation(this.program, 'a_texCoord'),
            u_resolution:      gl.getUniformLocation(this.program, 'u_resolution'),
            u_canvasTexture:   gl.getUniformLocation(this.program, 'u_canvasTexture'),
            u_brushTexture:    gl.getUniformLocation(this.program, 'u_brushTexture'),
            u_brushColor:      gl.getUniformLocation(this.program, 'u_brushColor'),
            u_currentPosition: gl.getUniformLocation(this.program, 'u_currentPosition'),
            u_brushRadius:     gl.getUniformLocation(this.program, 'u_brushRadius'),
            u_baseMixStrength: gl.getUniformLocation(this.program, 'u_baseMixStrength'),
            u_useFalloff:      gl.getUniformLocation(this.program, 'u_useFalloff'),
            u_smearDir:        gl.getUniformLocation(this.program, 'u_smearDir'),
            u_smearLen:        gl.getUniformLocation(this.program, 'u_smearLen'),
            u_disableSmear:    gl.getUniformLocation(this.program, 'u_disableSmear'),
            u_smudgeAlpha:     gl.getUniformLocation(this.program, 'u_smudgeAlpha'),
            u_isSmudge:        gl.getUniformLocation(this.program, 'u_isSmudge'),
            u_smudgeSampleRadius: gl.getUniformLocation(this.program, 'u_smudgeSampleRadius'),
            u_smudgeAngle:        gl.getUniformLocation(this.program, 'u_smudgeAngle'),
            u_smudgeSnapshot:     gl.getUniformLocation(this.program, 'u_smudgeSnapshot'),
            u_smudgeMix:          gl.getUniformLocation(this.program, 'u_smudgeMix'),
            u_smudgeHeatmap:      gl.getUniformLocation(this.program, 'u_smudgeHeatmap'),
            u_wetHeatmap:         gl.getUniformLocation(this.program, 'u_wetHeatmap'),
            u_depositHeatmap:     gl.getUniformLocation(this.program, 'u_depositHeatmap'),
            u_isWatercolor:       gl.getUniformLocation(this.program, 'u_isWatercolor'),
            u_wetSmudgeMix:       gl.getUniformLocation(this.program, 'u_wetSmudgeMix'),
            u_wetDepositPeak:     gl.getUniformLocation(this.program, 'u_wetDepositPeak'),
            u_wetBleedRadius:     gl.getUniformLocation(this.program, 'u_wetBleedRadius'),
            u_wetBleedMix:        gl.getUniformLocation(this.program, 'u_wetBleedMix'),
            u_wetColdMix:         gl.getUniformLocation(this.program, 'u_wetColdMix'),
            u_wetSmearReach:      gl.getUniformLocation(this.program, 'u_wetSmearReach'),
        };

        for (const name of this._getExtraUniformNames()) {
            this.locations[name] = gl.getUniformLocation(this.program, name);
        }

        BaseWebGLPainter._programCache.main.set(cacheKey, {
            program: this.program,
            locations: this.locations,
        });
    }

    createShader(type, source) {
        const gl = this.gl;
        const shader = gl.createShader(type);
        gl.shaderSource(shader, source);
        gl.compileShader(shader);
        if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
            console.error('着色器编译错误:', gl.getShaderInfoLog(shader));
            gl.deleteShader(shader);
            return null;
        }
        return shader;
    }

    createProgram(vs, fs) {
        const gl = this.gl;
        const program = gl.createProgram();
        gl.attachShader(program, vs);
        gl.attachShader(program, fs);
        gl.linkProgram(program);
        if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
            console.error('程序链接错误:', gl.getProgramInfoLog(program));
            return null;
        }
        return program;
    }

    // ─────────────────────────────────────────────
    // 纹理 / Framebuffer / 几何体
    // ─────────────────────────────────────────────

    setupTextures() {
        const w = this.canvas.width;
        const h = this.canvas.height;
        this.textures.canvas         = this.createEmptyTexture(w, h);
        this.textures.temp           = this.createEmptyTexture(w, h);
        this.textures.smudgeSnapshot  = this.createEmptyTexture(w, h);
        this.setupHeatmapTextures(w, h);
        // wetHeatmap 纹理/FB 由 heatmap.js 统一建立别名，无需单独创建
    }

    setupFramebuffers() {
        const gl = this.gl;

        this.framebuffers.canvas = gl.createFramebuffer();
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.framebuffers.canvas);
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, this.textures.canvas, 0);

        this.framebuffers.temp = gl.createFramebuffer();
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.framebuffers.temp);
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, this.textures.temp, 0);

        if (gl.checkFramebufferStatus(gl.FRAMEBUFFER) !== gl.FRAMEBUFFER_COMPLETE) {
            console.error('Framebuffer 创建失败');
        }

        // 辅助 read FB：仅用于 drawBrush 中 copyTexImage2D，不参与 swapTextures
        this._copyReadFB = gl.createFramebuffer();

        this.setupHeatmapFramebuffers();
        // wetHeatmap FB 由 heatmap.js 统一建立别名，无需单独创建

        // 启动 wet/wetMask 常驻衰减 task（与水彩 RAF 解耦，抬笔后仍持续衰减）
        this.startHeatmapDecay();

        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    }

    setupGeometry() {
        // 主 program 的 position/texCoord VBO 整个会话复用，避免切引擎时反复重建
        const cached = BaseWebGLPainter._programCache.mainGeometry;
        if (cached) {
            this.buffers.position = cached.position;
            this.buffers.texCoord = cached.texCoord;
            this.pixelAlignmentOffset = 0.0;
            return;
        }
        const gl = this.gl;
        this.buffers.position = gl.createBuffer();

        const texCoords = new Float32Array([0, 0, 1, 0, 0, 1, 1, 1]);
        this.buffers.texCoord = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, this.buffers.texCoord);
        gl.bufferData(gl.ARRAY_BUFFER, texCoords, gl.STATIC_DRAW);

        this.pixelAlignmentOffset = 0.0;

        BaseWebGLPainter._programCache.mainGeometry = {
            position: this.buffers.position,
            texCoord: this.buffers.texCoord,
        };
    }

    createEmptyTexture(width, height) {
        const gl = this.gl;
        const texture = gl.createTexture();
        gl.bindTexture(gl.TEXTURE_2D, texture);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, width, height, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        return texture;
    }

    createTextureFromImage(image) {
        const gl = this.gl;
        const texture = gl.createTexture();
        gl.bindTexture(gl.TEXTURE_2D, texture);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, image);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        return texture;
    }

    createBrushTextureFromCanvas(brushCanvas) {
        return this.createTextureFromImage(brushCanvas);
    }

    // ─────────────────────────────────────────────
    // blit 程序（历史还原用，WebGL1 全屏四边形）
    // ─────────────────────────────────────────────

    _initBlitProgram() {
        const cached = BaseWebGLPainter._programCache.blit;
        if (cached) {
            this._blitProgram = cached.program;
            this._blitLocations = cached.locations;
            this._blitBuffer = cached.buffer;
            return;
        }
        const gl = this.gl;

        const vs = this.createShader(gl.VERTEX_SHADER, `#version 300 es
            in vec2 a_clipPos;
            void main() { gl_Position = vec4(a_clipPos, 0, 1); }
        `);
        const fs = this.createShader(gl.FRAGMENT_SHADER, `#version 300 es
            precision mediump float;
            uniform sampler2D u_src;
            uniform vec2 u_resolution;
            out vec4 outColor;
            void main() {
                vec2 uv = gl_FragCoord.xy / u_resolution;
                outColor = texture(u_src, uv);
            }
        `);
        this._blitProgram = this.createProgram(vs, fs);
        this._blitLocations = {
            a_clipPos:    gl.getAttribLocation(this._blitProgram, 'a_clipPos'),
            u_src:        gl.getUniformLocation(this._blitProgram, 'u_src'),
            u_resolution: gl.getUniformLocation(this._blitProgram, 'u_resolution'),
        };

        this._blitBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, this._blitBuffer);
        gl.bufferData(gl.ARRAY_BUFFER,
            new Float32Array([-1, -1,  1, -1,  -1, 1,  1, 1]),
            gl.STATIC_DRAW);
        gl.bindBuffer(gl.ARRAY_BUFFER, null);

        BaseWebGLPainter._programCache.blit = {
            program:  this._blitProgram,
            locations: this._blitLocations,
            buffer:   this._blitBuffer,
        };
    }

    // ─────────────────────────────────────────────
    // 绘制
    // ─────────────────────────────────────────────

    setMixStrength(strength) {
        this.baseMixStrength = Math.max(0.01, Math.min(1.0, strength));
    }

    getMixStrength() {
        return this.baseMixStrength;
    }

    /**
     * 设置水彩湿度（0~1）。
     * 对齐 km-paint：cap 固定为 WET_HEAT_CAP_STEP，湿度只影响衰减/扩散等其他参数，不抬高 wetHeatmap 封顶。
     * 原映射 0.25+0.75w 在默认 0.5 湿度下让 cap=0.625，wetHeatmap 整体偏红。
     */
    setWetness(wetness) {
        const w = Math.max(0, Math.min(1, wetness));
        this._wetness = w;
        this._wetHeatCapBase = WET_HEAT_CAP_STEP;
        this._recomputeWetCache(w);
    }

    /**
     * 落笔时调用：把当前 canvas 纹理复制到 smudgeSnapshot，
     * 涂抹期间 shader 从此快照采样，避免颜色被反复稀释变灰。
     * 同时清零热度图，让新笔从热度 0 开始累积。
     */
    captureSmudgeSnapshot() {
        // 新笔触开始，取消定时清零，确保衰减 RAF 在运行
        this._resetHeatmapFade();
        this.startHeatmapFadeOut();

        const gl = this.gl;
        const cw = this.canvas.width;
        const ch = this.canvas.height;
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.framebuffers.canvas);
        gl.bindTexture(gl.TEXTURE_2D, this.textures.smudgeSnapshot);
        gl.copyTexSubImage2D(gl.TEXTURE_2D, 0, 0, 0, 0, 0, cw, ch);
        gl.bindTexture(gl.TEXTURE_2D, null);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);

        // 清零热度图（每笔重新累积）
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.framebuffers.smudgeHeatmap);
        gl.clearColor(0, 0, 0, 1);
        gl.clear(gl.COLOR_BUFFER_BIT);
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.framebuffers.smudgeHeatTemp);
        gl.clearColor(0, 0, 0, 1);
        gl.clear(gl.COLOR_BUFFER_BIT);

    }

    /**
     * 绘制笔触（核心方法）
     * 返回脏区矩形 {x, y, w, h}
     */
    drawBrush(x, y, size, colorRGB, brushCanvas,
              useFalloff = true,
              smearDir = { x: 0, y: 0 }, smearLen = 0,
              disableSmear = false, smudgeAlpha = 1.0, u_isSmudge = false, smudgeSampleRadius = 0, smudgeAngle = 0,
              brushRotation = 0, smudgeMix = 0, isWatercolor = false) {
        const gl = this.gl;
        const cw = this.canvas.width;
        const ch = this.canvas.height;

        const halfSize = size / 2;
        const rx0 = Math.max(0, Math.floor(x - halfSize));
        const ry0 = Math.max(0, Math.floor(y - halfSize));
        const rx1 = Math.min(cw, Math.ceil(x + halfSize));
        const ry1 = Math.min(ch, Math.ceil(y + halfSize));
        const rw = rx1 - rx0;
        const rh = ry1 - ry0;
        if (rw <= 0 || rh <= 0) return null;

        if (brushCanvas !== this.lastBrushCanvas) {
            if (this.currentBrushTexture) gl.deleteTexture(this.currentBrushTexture);
            this.currentBrushTexture = this.createBrushTextureFromCanvas(brushCanvas);
            this.lastBrushCanvas = brushCanvas;
        }

        // 水彩模式：向 wetHeatmap 注热，同时走主混色 pass（mixbox_lerp 负责颜色，RAF 的 _applyWetColor 叠加湿纸效果）
        if (isWatercolor) {
            // 对齐 km-paint：cap 固定为 _wetHeatCapBase（来自湿度滑条），不再做方向调制。
            // 原方向 bump 逻辑会让转向时 cap 一路冲到 1.0，导致 wetHeatmap 比 km-paint 积累快 ~4×，
            // 表现为湿度持续偏高、扩散柔边覆盖噪点。
            if (this._wetHeatCap === undefined) {
                this._wetHeatCap = this._wetHeatCapBase ?? WET_HEAT_CAP_STEP;
            }
            this.updateWetHeatmap(x, y, size, brushCanvas, useFalloff, HEAT_ACCUMULATE_STEP);
            this._wetSmearDir = smearDir;
            this._wetSmearLen = smearLen;
        }

        // 渲染前先把 canvas 完整同步到 temp，保证 temp 笔刷区域之外的像素正确
        // 注意：不能用 this.framebuffers.canvas（会随 swapTextures 轮换），
        // 必须用辅助 FB 直接绑定当前 textures.canvas 来读取。
        gl.bindFramebuffer(gl.FRAMEBUFFER, this._copyReadFB);
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, this.textures.canvas, 0);
        gl.bindTexture(gl.TEXTURE_2D, this.textures.temp);
        gl.copyTexSubImage2D(gl.TEXTURE_2D, 0, 0, 0, 0, 0, cw, ch);
        gl.bindTexture(gl.TEXTURE_2D, null);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);

        gl.useProgram(this.program);
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.framebuffers.temp);
        gl.viewport(0, 0, cw, ch);

        // 子类绑定 LUT（各自负责纹理槽）
        this._bindLUT();

        gl.uniform2f(this.locations.u_resolution, cw, ch);
        gl.uniform4f(this.locations.u_brushColor, colorRGB.r, colorRGB.g, colorRGB.b, 1.0);
        gl.uniform2f(this.locations.u_currentPosition, x, y);
        gl.uniform1f(this.locations.u_brushRadius, size / 2);
        gl.uniform1f(this.locations.u_baseMixStrength, this.baseMixStrength);
        gl.uniform1f(this.locations.u_useFalloff, +useFalloff);
        gl.uniform2f(this.locations.u_smearDir, smearDir.x, smearDir.y);
        gl.uniform1f(this.locations.u_smearLen, smearLen);
        gl.uniform1f(this.locations.u_disableSmear, disableSmear ? 1.0 : 0.0);
        gl.uniform1f(this.locations.u_smudgeAlpha, smudgeAlpha);
        gl.uniform1f(this.locations.u_isSmudge, u_isSmudge ? 1.0 : 0.0);
        gl.uniform1f(this.locations.u_smudgeSampleRadius, smudgeSampleRadius);
        gl.uniform1f(this.locations.u_smudgeAngle, u_isSmudge ? smudgeAngle : brushRotation);
        gl.uniform1f(this.locations.u_smudgeMix, smudgeMix);

        // 涂抹快照纹理固定绑定到 TEXTURE3，供 shader 采样冻结的起始画布
        gl.activeTexture(gl.TEXTURE3);
        gl.bindTexture(gl.TEXTURE_2D, this.textures.smudgeSnapshot);
        gl.uniform1i(this.locations.u_smudgeSnapshot, 3);

        // 热度图绑定到 TEXTURE4，供 shader 读取当前累积热度
        gl.activeTexture(gl.TEXTURE4);
        gl.bindTexture(gl.TEXTURE_2D, this.textures.smudgeHeatmap);
        gl.uniform1i(this.locations.u_smudgeHeatmap, 4);

        // 湿纸热度图绑定到 TEXTURE5（非水彩时传空纹理，shader 不使用）
        gl.activeTexture(gl.TEXTURE5);
        gl.bindTexture(gl.TEXTURE_2D, this.textures.wetHeatmap);
        gl.uniform1i(this.locations.u_wetHeatmap, 5);
        gl.activeTexture(gl.TEXTURE6);
        gl.bindTexture(gl.TEXTURE_2D, this.textures.depositHeatmap);
        gl.uniform1i(this.locations.u_depositHeatmap, 6);
        // wet低→颜料浓（coldMix高）；wet高→晕染强、smudge强（bleedMix/bleedRadius/smudgeMix高）
        gl.uniform1f(this.locations.u_isWatercolor, isWatercolor ? 1.0 : 0.0);
        if (isWatercolor) {
            const wc = this._wetCache;
            gl.uniform1f(this.locations.u_wetSmudgeMix,   wc.smudgeMix);
            gl.uniform1f(this.locations.u_wetDepositPeak, WET_DEPOSIT_PEAK);
            gl.uniform1f(this.locations.u_wetBleedRadius, wc.bleedRadius);
            gl.uniform1f(this.locations.u_wetBleedMix,    wc.bleedMix);
            gl.uniform1f(this.locations.u_wetColdMix,     wc.coldMix);
            gl.uniform1f(this.locations.u_wetSmearReach,  WET_SMEAR_REACH);
        } else {
            gl.uniform1f(this.locations.u_wetSmudgeMix,   0.0);
            gl.uniform1f(this.locations.u_wetDepositPeak, 0.0);
            gl.uniform1f(this.locations.u_wetBleedRadius, 0.0);
            gl.uniform1f(this.locations.u_wetBleedMix,    0.0);
            gl.uniform1f(this.locations.u_wetColdMix,     0.0);
            gl.uniform1f(this.locations.u_wetSmearReach,  0.0);
        }

        const positions = this._quadPos;
        positions[0] = x - halfSize; positions[1] = y - halfSize;
        positions[2] = x + halfSize; positions[3] = y - halfSize;
        positions[4] = x - halfSize; positions[5] = y + halfSize;
        positions[6] = x + halfSize; positions[7] = y + halfSize;
        this._disableAllVertexAttribs();
        gl.bindBuffer(gl.ARRAY_BUFFER, this.buffers.position);
        gl.bufferData(gl.ARRAY_BUFFER, positions, gl.DYNAMIC_DRAW);
        gl.enableVertexAttribArray(this.locations.a_position);
        gl.vertexAttribPointer(this.locations.a_position, 2, gl.FLOAT, false, 0, 0);

        gl.bindBuffer(gl.ARRAY_BUFFER, this.buffers.texCoord);
        gl.enableVertexAttribArray(this.locations.a_texCoord);
        gl.vertexAttribPointer(this.locations.a_texCoord, 2, gl.FLOAT, false, 0, 0);

        gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
        this.swapTextures();
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);

        // 涂抹模式：每次 drawcall 后更新热度图
        if (u_isSmudge) {
            this.updateSmudgeHeatmap(x, y, size, brushCanvas, useFalloff, HEAT_ACCUMULATE_STEP);
        }

        // 水彩 smudge 已内联进主 pass shader（u_wetSmudgeMix），无需额外 pass

        return { x: rx0, y: ry0, w: rw, h: rh };
    }

    /**
     * 把离屏 canvas 纹理 blit 到 default framebuffer（屏幕）
     */
    flush() {
        const gl = this.gl;
        const cw = this.canvas.width;
        const ch = this.canvas.height;
        gl.useProgram(this._blitProgram);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        gl.viewport(0, 0, cw, ch);

        for (let i = 0; i < 4; i++) {
            gl.activeTexture(gl.TEXTURE0 + i);
            gl.bindTexture(gl.TEXTURE_2D, null);
        }

        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, this.textures.canvas);
        gl.uniform1i(this._blitLocations.u_src, 0);
        gl.uniform2f(this._blitLocations.u_resolution, cw, ch);

        this._disableAllVertexAttribs();

        gl.bindBuffer(gl.ARRAY_BUFFER, this._blitBuffer);
        gl.enableVertexAttribArray(this._blitLocations.a_clipPos);
        gl.vertexAttribPointer(this._blitLocations.a_clipPos, 2, gl.FLOAT, false, 0, 0);

        gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
        gl.bindTexture(gl.TEXTURE_2D, null);

        // 调试：热度图 / 湿纸 overlay（互斥，各自检查自己的 flag）
        if (this._debugHeatmapEnabled)  this._flushDebugHeatmap(this._debugHeatOpacity ?? 1.0);
        if (this._debugWetPaperEnabled) this._flushDebugWetPaper(this._debugHeatOpacity ?? 1.0);
        if (this._debugDepositHeatmapEnabled) this._flushDebugDepositHeatmap(this._debugHeatOpacity ?? 1.0);
        if (this._debugWetMaskHeatmapEnabled) this._flushDebugWetMaskHeatmap(this._debugHeatOpacity ?? 1.0);
    }

    /**
     * 禁用所有 vertex attribute。
     * WebGL 的 attribute enabled 状态是全局共享的（不随 program 切换重置），
     * 切换 program 前统一禁用，避免上个 program 启用的 attribute 在当前 program 上
     * 造成 "no buffer is bound to enabled attribute" 错误。
     */
    _disableAllVertexAttribs() {
        const gl = this.gl;
        if (this._maxVertexAttribs === undefined) {
            this._maxVertexAttribs = gl.getParameter(gl.MAX_VERTEX_ATTRIBS);
        }
        for (let i = 0; i < this._maxVertexAttribs; i++) {
            gl.disableVertexAttribArray(i);
        }
    }

    swapTextures() {
        const gl = this.gl;
        for (let i = 0; i < 4; i++) {
            gl.activeTexture(gl.TEXTURE0 + i);
            gl.bindTexture(gl.TEXTURE_2D, null);
        }
        [this.textures.canvas, this.textures.temp] =
            [this.textures.temp, this.textures.canvas];
        [this.framebuffers.canvas, this.framebuffers.temp] =
            [this.framebuffers.temp, this.framebuffers.canvas];
    }

    // ─────────────────────────────────────────────
    // 像素读写
    // ─────────────────────────────────────────────

    /**
     * CPU 像素数据 → WebGL 纹理（屏幕坐标，Y向下）
     */
    writeFromPixels(pixels, w, h) {
        const gl = this.gl;
        gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
        gl.bindTexture(gl.TEXTURE_2D, this.textures.canvas);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, w, h, 0, gl.RGBA, gl.UNSIGNED_BYTE, pixels);
        gl.bindTexture(gl.TEXTURE_2D, this.textures.temp);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, w, h, 0, gl.RGBA, gl.UNSIGNED_BYTE, pixels);
        gl.bindTexture(gl.TEXTURE_2D, null);
        gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
        this.flush();
    }

    readPixelByte(x, y) {
        const gl = this.gl;
        const glY = this.canvas.height - 1 - y;
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.framebuffers.canvas);
        const pixels = new Uint8Array(4);
        gl.readPixels(x, glY, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, pixels);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        return { r: pixels[0], g: pixels[1], b: pixels[2] };
    }

    readPixelRegion(x, y, w, h) {
        const gl = this.gl;
        const cw = this.canvas.width;
        const ch = this.canvas.height;
        const sx = Math.max(0, x);
        const sy = Math.max(0, y);
        const sw = Math.min(w, cw - sx);
        const sh = Math.min(h, ch - sy);
        const glY = ch - sy - sh;
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.framebuffers.canvas);
        const pixels = new Uint8Array(sw * sh * 4);
        gl.readPixels(sx, glY, sw, sh, gl.RGBA, gl.UNSIGNED_BYTE, pixels);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        const flipped = new Uint8ClampedArray(pixels.length);
        const rowSize = sw * 4;
        for (let row = 0; row < sh; row++) {
            flipped.set(
                pixels.subarray((sh - 1 - row) * rowSize, (sh - row) * rowSize),
                row * rowSize
            );
        }
        return flipped;
    }

    // ─────────────────────────────────────────────
    // 清空
    // ─────────────────────────────────────────────

    clear(color = { r: 1, g: 1, b: 1 }) {
        const gl = this.gl;
        for (let i = 0; i < 8; i++) {
            gl.activeTexture(gl.TEXTURE0 + i);
            gl.bindTexture(gl.TEXTURE_2D, null);
        }
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.framebuffers.canvas);
        gl.clearColor(color.r, color.g, color.b, 1.0);
        gl.clear(gl.COLOR_BUFFER_BIT);

        gl.bindFramebuffer(gl.FRAMEBUFFER, this.framebuffers.temp);
        gl.clearColor(color.r, color.g, color.b, 1.0);
        gl.clear(gl.COLOR_BUFFER_BIT);

        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        this.flush();
    }

    // ─────────────────────────────────────────────
    // GPU 历史记录系统
    // ─────────────────────────────────────────────

    /**
     * 分配一个 GPU slot（纹理 + framebuffer）
     * 如果空闲池有则复用，否则新建；超出上限时驱逐最老可驱逐帧
     */
    _acquireGpuSlot() {
        if (this._gpuFreeSlots.length > 0) {
            return this._gpuFreeSlots.pop();
        }

        // 检查是否还有预算新建
        const usedSlots = this._history.filter(f => f.gpuSlot !== null).length;
        if (usedSlots < this._maxGpuSlots) {
            const slot = this._createGpuSlot();
            if (slot) return slot;
            // 创建失败（已触发降级）→ 退路：驱逐最老帧
        }

        // 超出预算或创建失败，驱逐最老的、不是当前步的帧
        return this._evictOldestGpuSlot();
    }

    _createGpuSlot() {
        const gl = this.gl;
        const cw = this.canvas.width;
        const ch = this.canvas.height;

        // 清空先前的错误状态，避免误判
        while (gl.getError() !== gl.NO_ERROR) {}

        const tex = this.createEmptyTexture(cw, ch);
        const err = gl.getError();
        if (!tex || err === gl.OUT_OF_MEMORY) {
            if (tex) gl.deleteTexture(tex);
            this._tryDowngradeGpuBudget();
            return null;
        }

        const fb  = gl.createFramebuffer();
        gl.bindFramebuffer(gl.FRAMEBUFFER, fb);
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);

        return { tex, fb };
    }

    /**
     * 检测到 GPU 分配失败时降级到备用预算。
     * 只降级一次（再失败就保持 MIN 保底，后续靠 CPU 备份救场）。
     */
    _tryDowngradeGpuBudget() {
        if (this._gpuBudgetDowngraded) return;
        this._gpuBudgetDowngraded = true;
        const oldMax = this._maxGpuSlots;
        this._calcGpuBudget(GPU_BUDGET_FALLBACK_MB);
        console.warn(`[GPU] 分配失败，历史槽位 ${oldMax} → ${this._maxGpuSlots}`);
        try {
            if (typeof window !== 'undefined' && typeof window.gtag === 'function') {
                window.gtag('event', 'gpu_budget_downgrade', {
                    canvas_w: this.canvas.width,
                    canvas_h: this.canvas.height,
                    old_slots: oldMax,
                    new_slots: this._maxGpuSlots
                });
            }
        } catch (_) {}
    }

    _evictOldestGpuSlot() {
        // 从最老帧开始找可驱逐的（不是当前步）
        for (let i = 0; i < this._history.length; i++) {
            const frame = this._history[i];
            if (frame.gpuSlot === null) continue;
            if (i === this._historyStep) continue;

            if (!frame.cpuReady) {
                // CPU 数据还没准备好，强制同步读一次
                this._syncReadFrameToCPU(frame);
            }
            const slot = frame.gpuSlot;
            frame.gpuSlot = null;
            return slot;
        }

        // 所有帧都是当前步（理论上不会发生），新建一个
        console.warn('BaseWebGLPainter: 无法驱逐任何帧，强制新建 GPU slot');
        const slot = this._createGpuSlot();
        if (slot) return slot;
        // 极端兜底：连新建都失败（极小显存），复用当前步的 slot
        // 这里返回 null 让上层决定是否跳过保存这一帧
        console.error('BaseWebGLPainter: GPU 分配彻底失败，跳过本次历史保存');
        return null;
    }

    /** 读回存储用像素并就地翻转行；只额外分配一行，不再复制整帧。 */
    _readPixelsForStorage(framebuffer, w, h) {
        const gl = this.gl;
        const raw = new Uint8Array(w * h * 4);
        gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
        try {
            gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, raw);
        } finally {
            gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        }
        const rowSize = w * 4;
        const row = new Uint8Array(rowSize);
        for (let top = 0, bottom = (h - 1) * rowSize; top < bottom; top += rowSize, bottom -= rowSize) {
            row.set(raw.subarray(top, top + rowSize));
            raw.copyWithin(top, bottom, bottom + rowSize);
            raw.set(row, bottom);
        }
        // 同一块独占 buffer 的视图；每次读回仍返回独立快照，不复用历史帧。
        return new Uint8ClampedArray(raw.buffer);
    }

    /** 同步从当前 canvas framebuffer 读取像素到 frame.cpuPixels（GPU slot 无法分配时的兜底）*/
    _readCanvasToCPU(frame) {
        const cw = this.canvas.width;
        const ch = this.canvas.height;
        try {
            frame.cpuPixels = this._readPixelsForStorage(this.framebuffers.canvas, cw, ch);
            frame.cpuReady  = true;
        } catch (e) {
            console.error('BaseWebGLPainter: readPixels 失败', e);
        }
    }

    /** 同步从 GPU 读取帧数据到 CPU（仅在驱逐前必要时调用）*/
    _syncReadFrameToCPU(frame) {
        if (frame.cpuReady || !frame.gpuSlot) return;
        const cw = this.canvas.width;
        const ch = this.canvas.height;

        frame.cpuPixels = this._readPixelsForStorage(frame.gpuSlot.fb, cw, ch);
        frame.cpuReady  = true;

        // 取消 idle 任务（已同步完成）
        this._cancelIdleBackup(frame);
    }

    /**
     * 把当前 canvas framebuffer 用 copyTexImage2D 保存到 slot.tex
     * 不需要 readPixels，纯 GPU 操作
     */
    _copyCanvasToSlot(slot) {
        const gl = this.gl;
        const cw = this.canvas.width;
        const ch = this.canvas.height;
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.framebuffers.canvas);
        gl.bindTexture(gl.TEXTURE_2D, slot.tex);
        gl.copyTexSubImage2D(gl.TEXTURE_2D, 0, 0, 0, 0, 0, cw, ch);
        gl.bindTexture(gl.TEXTURE_2D, null);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    }

    /**
     * 用 blit 程序把 slot.tex 渲染回 canvas framebuffer（及 temp）
     */
    _copySlotToCanvas(slot) {
        const gl = this.gl;
        const cw = this.canvas.width;
        const ch = this.canvas.height;

        gl.useProgram(this._blitProgram);
        gl.viewport(0, 0, cw, ch);

        // 解绑所有纹理，防止反馈
        for (let i = 0; i < 4; i++) {
            gl.activeTexture(gl.TEXTURE0 + i);
            gl.bindTexture(gl.TEXTURE_2D, null);
        }

        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, slot.tex);
        gl.uniform1i(this._blitLocations.u_src, 0);
        gl.uniform2f(this._blitLocations.u_resolution, cw, ch);

        this._disableAllVertexAttribs();
        gl.bindBuffer(gl.ARRAY_BUFFER, this._blitBuffer);
        gl.enableVertexAttribArray(this._blitLocations.a_clipPos);
        gl.vertexAttribPointer(this._blitLocations.a_clipPos, 2, gl.FLOAT, false, 0, 0);

        // → canvas framebuffer
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.framebuffers.canvas);
        gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

        // 同步 temp 纹理（复制 canvas framebuffer 内容，无额外 draw call）
        gl.bindTexture(gl.TEXTURE_2D, this.textures.temp);
        gl.copyTexSubImage2D(gl.TEXTURE_2D, 0, 0, 0, 0, 0, cw, ch);

        gl.bindTexture(gl.TEXTURE_2D, null);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        this.flush();
    }

    // ─────────────────────────────────────────────
    // 历史记录公开 API
    // ─────────────────────────────────────────────

    /**
     * 压入当前画布状态为新历史帧
     * 裁掉当前步之后的所有帧，然后保存快照
     */
    pushHistoryFrame() {
        // 丢弃当前步之后的帧。
        // 先从 _history 断开引用让新帧不被它们干扰，然后分批异步释放，
        // 避免一次性解引用大量 Blob / 同步扫 Map 造成笔画结束时的卡顿。
        const discarded = this._history.splice(this._historyStep + 1);
        if (discarded.length > 0) this._scheduleAsyncRelease(discarded);

        const slot = this._acquireGpuSlot();
        const frame = {
            id:        this._frameCounter++,
            timestamp: performance.now(),
            gpuSlot:   slot,
            cpuPixels: null,
            cpuReady:  false,
        };
        if (slot) {
            this._copyCanvasToSlot(slot);
        } else {
            // GPU 彻底无法分配：同步 readPixels 到 CPU 保底，避免撤销链断档
            console.warn('BaseWebGLPainter: GPU 分配失败，历史帧回退 CPU 快照');
            this._readCanvasToCPU(frame);
            if (!frame.cpuReady) return; // 连 CPU 也失败（极罕见）→ 放弃
        }

        this._history.push(frame);

        // 软上限：超过 GPU slot 配额一定缓冲后驱逐最老帧
        if (this._history.length > this._maxGpuSlots + HISTORY_OVERFLOW_BUFFER) {
            const oldest = this._history.shift();
            this._releaseFrame(oldest);
        }
        // 硬上限：防止长时间绘制时 cpuBlob 无限累积
        while (this._history.length > HISTORY_FRAMES_HARD_CAP) {
            const oldest = this._history.shift();
            this._releaseFrame(oldest);
        }

        this._historyStep = this._history.length - 1;

        // 异步写 CPU 备份
        this._scheduleIdleBackup(frame);
    }

    /**
     * 跳转到指定步骤（撤销/重做）
     * @param {number} step - _history 数组下标
     * @returns {boolean} 是否成功
     */
    async restoreHistoryFrame(step) {
        if (step < 0 || step >= this._history.length) return false;

        const frame = this._history[step];
        const seq = ++this._restoreSeq;
        let pixels = null;

        if (frame.gpuSlot) {
            // GPU 路径：blit，零 readPixels（同步完成，无竞态）
            this._copySlotToCanvas(frame.gpuSlot);
        } else if (frame.cpuPixels) {
            pixels = frame.cpuPixels;
        } else if (this._decompressCache.has(frame.id)) {
            pixels = this._decompressCache.get(frame.id);
        } else if (frame.cpuBlob) {
            // 从压缩 blob 解压
            try {
                pixels = await this._decompressFrame(frame);
            } catch (e) {
                console.warn('BaseWebGLPainter: 解压失败', e);
                return false;
            }
            // 异步返回后校验：如果期间又触发了新的 restore（用户连续点撤销/重做），丢弃本次结果
            if (seq !== this._restoreSeq || this._disposed) return false;
        } else {
            console.warn('BaseWebGLPainter: 帧数据不可用');
            return false;
        }

        if (pixels) {
            this.writeFromPixels(pixels, this.canvas.width, this.canvas.height);
            // 回写 GPU slot，下次零延迟
            const slot = this._acquireGpuSlot();
            if (slot) {
                this._copyCanvasToSlot(slot);
                frame.gpuSlot = slot;
            }
        }

        // 方向追踪：用于预解下一帧
        if (this._lastRestoreStep >= 0) {
            const diff = step - this._lastRestoreStep;
            if (diff !== 0) this._lastRestoreDir = diff > 0 ? 1 : -1;
        }
        this._lastRestoreStep = step;
        this._historyStep = step;

        // 触发朝同方向预解下一帧
        this._prefetchAdjacentFrame();
        return true;
    }

    /** 清空历史记录（切换引擎时调用）*/
    clearHistory() {
        // 取消所有 idle 任务
        for (const frame of this._history) {
            this._cancelIdleBackup(frame);
        }
        // 释放所有 GPU slot（放回空闲池，不销毁纹理，复用成本低）
        for (const frame of this._history) {
            if (frame.gpuSlot) {
                this._gpuFreeSlots.push(frame.gpuSlot);
                frame.gpuSlot = null;
            }
        }
        this._history = [];
        this._historyStep = -1;

        // 打断飞行中的压缩任务：reject 所有 pending、terminate worker、清解压缓存。
        // Why: _cancelIdleBackup 只能取消 requestIdleCallback 队列里还没触发的任务；
        // 已经进入 worker 的 compress/decompress 会继续跑完才停，iPad 上 clear 后仍会吃 CPU。
        if (this._workerPending && this._workerPending.size > 0) {
            for (const { reject } of this._workerPending.values()) {
                reject(new Error('clearHistory: worker terminated'));
            }
            this._workerPending.clear();
        }
        if (this._historyWorker) {
            try { this._historyWorker.terminate(); } catch (_) {}
            this._historyWorker = null;
        }
        if (this._decompressCache) this._decompressCache.clear();
        if (this._pendingIdle) this._pendingIdle.clear();
    }

    /** 历史记录总帧数 */
    getHistoryLength() {
        return this._history.length;
    }

    /** 当前步骤指针 */
    getHistoryStep() {
        return this._historyStep;
    }

    // ─────────────────────────────────────────────
    // 历史压缩 Worker
    // ─────────────────────────────────────────────

    _ensureHistoryWorker() {
        if (this._historyWorker) return this._historyWorker;
        try {
            // 基于 base-painter.js 的 URL 解析 worker 路径，避免 app 部署在子目录时相对路径失效
            const base = BaseWebGLPainter._scriptURL;
            const workerURL = globalThis.__MPX_WORKER_URL || (base ? new URL('./history-worker.js', base).href : 'js/history-worker.js');
            this._historyWorker = new Worker(workerURL);
            this._historyWorker.onmessage = (e) => {
                const { type, id } = e.data;
                const entry = this._workerPending.get(id);
                if (!entry) return;
                this._workerPending.delete(id);
                if (type === 'error') entry.reject(new Error(e.data.reason));
                else if (type === 'compressed') entry.resolve(e.data.blob);
                else if (type === 'decompressed') entry.resolve(new Uint8ClampedArray(e.data.pixels));
            };
            const worker = this._historyWorker;
            const failWorker = (err) => {
                if (this._historyWorker !== worker) return;
                console.error('[history-worker] error:', err);
                this._historyWorker = null;
                try { worker.terminate(); } catch (_) {}
                const pending = [...this._workerPending.values()];
                this._workerPending.clear();
                for (const { reject } of pending) reject(new Error(err.message || 'worker failed'));
            };
            worker.onerror = failWorker;
            worker.onmessageerror = failWorker;
        } catch (err) {
            console.warn('[history-worker] 创建失败，历史压缩禁用', err);
            this._historyWorker = null;
        }
        return this._historyWorker;
    }

    _workerRequest(msg, transfer) {
        const w = this._ensureHistoryWorker();
        if (!w) return Promise.reject(new Error('worker unavailable'));
        const id = ++this._workerMsgId;
        return new Promise((resolve, reject) => {
            this._workerPending.set(id, { resolve, reject });
            try {
                w.postMessage({ ...msg, id }, transfer || []);
            } catch (err) {
                this._workerPending.delete(id);
                reject(err);
            }
        });
    }

    /** 把已经读到 CPU 的帧压缩成 blob，压完释放 cpuPixels */
    async _compressFrame(frame) {
        if (!frame.cpuReady || !frame.cpuPixels || frame.cpuBlob) return;
        // 防止同一帧被多次压缩：idle 循环密集触发时，上一次 await 未完成前可能又被扫到
        if (frame._compressing) return;
        frame._compressing = true;
        const w = this.canvas.width;
        const h = this.canvas.height;
        const buf = frame.cpuPixels.buffer.slice(0); // 拷贝一份给 worker transfer
        try {
            const blob = await this._workerRequest(
                { type: 'compress', pixels: buf, w, h },
                [buf]
            );
            // 帧可能已经被丢弃
            if (!this._history.includes(frame)) return;
            frame.cpuBlob = blob;
            frame.cpuBlobW = w;
            frame.cpuBlobH = h;
            frame.cpuPixels = null; // 释放未压缩数据
        } catch (e) {
            // 压缩失败保留 cpuPixels
        } finally {
            frame._compressing = false;
        }
    }

    /**
     * idle 备份快路径：直接 GPU → readPixels(raw) → transfer 给 worker 做 Y 翻转+压缩。
     * 相比 _syncReadFrameToCPU + _compressFrame 的两步走，省去主线程的：
     *   1) Y 翻转 for-loop（大画布 ~5-10ms）
     *   2) cpuPixels.buffer.slice(0) 的 12MB 拷贝（~3-5ms）
     * 成功后 frame 直接进入 cpuBlob 状态，跳过 cpuReady/cpuPixels 中间态。
     * @returns {boolean} 是否成功发起（false 表示需走老路径兜底）
     */
    _idleBackupFrameDirect(frame) {
        if (frame.cpuReady || !frame.gpuSlot || frame._compressing) return false;
        const gl = this.gl;
        const cw = this.canvas.width;
        const ch = this.canvas.height;

        let raw;
        try {
            gl.bindFramebuffer(gl.FRAMEBUFFER, frame.gpuSlot.fb);
            raw = new Uint8Array(cw * ch * 4);
            gl.readPixels(0, 0, cw, ch, gl.RGBA, gl.UNSIGNED_BYTE, raw);
            gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        } catch (e) {
            console.error('BaseWebGLPainter: idle readPixels 失败', e);
            return false;
        }

        frame._compressing = true;
        const buf = raw.buffer; // 直接 transfer，主线程不再持有
        this._workerRequest(
            { type: 'compress', pixels: buf, w: cw, h: ch, flipY: true },
            [buf]
        ).then((blob) => {
            if (!this._history.includes(frame)) return;
            frame.cpuBlob = blob;
            frame.cpuBlobW = cw;
            frame.cpuBlobH = ch;
            frame.cpuReady = true; // 有 blob 即视为 CPU 备份就绪
        }).catch((e) => {
            // 失败：清掉 compressing 标记，下一次 idle 会走老路径兜底
            console.warn('BaseWebGLPainter: idle 压缩失败', e);
        }).finally(() => {
            frame._compressing = false;
            this._pendingIdle.delete(frame.id);
        });
        return true;
    }

    /** 从 blob 解压回 Uint8ClampedArray（带缓存） */
    async _decompressFrame(frame) {
        if (frame.cpuPixels) return frame.cpuPixels;
        if (this._decompressCache.has(frame.id)) {
            const px = this._decompressCache.get(frame.id);
            // LRU 触达
            this._decompressCache.delete(frame.id);
            this._decompressCache.set(frame.id, px);
            return px;
        }
        if (!frame.cpuBlob) return null;
        const pixels = await this._workerRequest({
            type: 'decompress',
            blob: frame.cpuBlob,
            w: frame.cpuBlobW,
            h: frame.cpuBlobH,
        });
        this._decompressCachePut(frame.id, pixels);
        return pixels;
    }

    _decompressCachePut(frameId, pixels) {
        if (this._decompressCache.has(frameId)) {
            this._decompressCache.delete(frameId);
        }
        this._decompressCache.set(frameId, pixels);
        while (this._decompressCache.size > this._decompressCacheMax) {
            const firstKey = this._decompressCache.keys().next().value;
            this._decompressCache.delete(firstKey);
        }
    }

    /**
     * 把"距离当前步较远"的帧异步压缩成 blob，释放 cpuPixels。
     * 每次只挑"最远离当前步"的一帧丢给 worker，避免一次 idle 就把几十帧全扔进队列：
     * - 减少主线程 ArrayBuffer slice(0) 拷贝次数
     * - 避免 worker 队列堆 N 份未完成任务，内存峰值爆炸
     * 下一次 idle 还会再扫，所以迟早都会压完。
     */
    _maybeCompressOldFrames() {
        const keepNear = HISTORY_UNCOMPRESSED_NEAR;
        let bestIdx = -1;
        let bestDist = keepNear;
        for (let i = 0; i < this._history.length; i++) {
            const frame = this._history[i];
            if (!frame.cpuReady || !frame.cpuPixels) continue;
            if (frame.cpuBlob) continue;
            if (frame._compressing) continue;
            const dist = Math.abs(i - this._historyStep);
            if (dist <= keepNear) continue;
            if (dist > bestDist) { bestDist = dist; bestIdx = i; }
        }
        if (bestIdx >= 0) {
            this._compressFrame(this._history[bestIdx]).catch(() => {});
        }
    }

    /** 朝上次撤销方向预解一帧（fire-and-forget） */
    _prefetchAdjacentFrame() {
        if (!this._lastRestoreDir) return;
        const next = this._historyStep + this._lastRestoreDir;
        if (next < 0 || next >= this._history.length) return;
        const frame = this._history[next];
        if (!frame) return;
        if (frame.gpuSlot || frame.cpuPixels) return;
        if (this._decompressCache.has(frame.id)) return;
        if (!frame.cpuBlob) return;
        // 异步解，不等结果
        this._decompressFrame(frame).catch(() => {});
    }

    // ─────────────────────────────────────────────
    // 异步 CPU 备份
    // ─────────────────────────────────────────────

    /**
     * app 侧在 beginStroke 里调：标记正在绘制，暂停 idle 备份调度。
     * 同时取消尚未到期的静默延迟：用户又画了，备份继续押后。
     */
    notifyStrokeStart() {
        this._strokeActive = true;
        if (this._quietDelayHandle !== null) {
            clearTimeout(this._quietDelayHandle);
            this._quietDelayHandle = null;
        }
    }

    /**
     * app 侧在 endStroke 里调：笔画结束，但不立即 schedule，
     * 等 STROKE_QUIET_DELAY_MS 内确认没有新笔画再真正发起 idle 备份。
     */
    notifyStrokeEnd() {
        this._strokeActive = false;
        if (this._quietDelayHandle !== null) clearTimeout(this._quietDelayHandle);
        this._quietDelayHandle = setTimeout(() => {
            this._quietDelayHandle = null;
            if (this._disposed) return;
            if (this._strokeActive) return;     // 期间又落笔了，放弃这次
            if (!this._backupDeferred) return;  // 没有待处理备份（正常 idle 已消化）
            this._backupDeferred = false;
            // 挑最新的帧代入 schedule（函数内部本就会扫描整个 history 找最需要处理的）
            if (this._history.length > 0) {
                this._scheduleIdleBackup(this._history[this._history.length - 1]);
            }
        }, STROKE_QUIET_DELAY_MS);
    }

    /**
     * 为新帧 schedule idle 备份，但全实例只保留一个 pending 任务。
     * 之前每个 pushHistoryFrame 都会 schedule 一次，用户画 30 笔就有 30 个 idle 回调排队，
     * 每个回调都做全画布 readPixels（~10-30ms）和 _maybeCompressOldFrames 扫全表，主线程压力巨大。
     * 现在改成：已有 pending 任务就不再 schedule；任务执行时找"最老的需要处理的帧"来做，
     * 处理完如果还有剩余的就再 schedule 一次。
     */
    _scheduleIdleBackup(frame) {
        // _pendingIdle 仍然用 frame.id 作 key（为了 _cancelIdleBackup 在 _releaseFrame 时能找到
        // 挂在这一帧上的 pending 记录）。但我们让同一时刻只存在一条"真实"idle handle。
        if (this._idleBackupScheduled) {
            // 记录这一帧需要备份即可；共用 idle 任务会扫到它
            this._pendingIdle.set(frame.id, { type: 'shared' });
            return;
        }

        // 笔画闸门：用户还在连续绘制时，Safari 的 rIC 会挤进 RAF 帧间隙造成卡顿。
        // 只记 shared 标记，等 notifyStrokeEnd 静默期过后再真正发起。
        if (this._strokeActive) {
            this._pendingIdle.set(frame.id, { type: 'shared' });
            this._backupDeferred = true;
            return;
        }

        this._idleBackupScheduled = true;

        const doBackup = () => {
            this._idleBackupScheduled = false;
            if (this._disposed) return;

            // A queued callback can run after drawing resumes. Keep the existing quiet-period gate.
            if (this._strokeActive) {
                this._pendingIdle.set(frame.id, { type: 'shared' });
                this._backupDeferred = true;
                return;
            }

            // 挑一个最需要备份的帧：有 GPU slot、还没 cpuReady、距当前步最远
            let readIdx = -1;
            let readDist = -1;
            for (let i = 0; i < this._history.length; i++) {
                const f = this._history[i];
                if (!f.gpuSlot || f.cpuReady) continue;
                if (f._compressing) continue;
                const d = Math.abs(i - this._historyStep);
                if (d > readDist) { readDist = d; readIdx = i; }
            }
            if (readIdx >= 0) {
                const f = this._history[readIdx];
                // 直接走 worker 快路径：主线程只做 readPixels，Y 翻转+压缩都在 worker。
                if (!this._idleBackupFrameDirect(f)) {
                    // 快路径起不来（极罕见），退回老路径：同步 readPixels + 翻转到 cpuPixels，再后续 _maybeCompressOldFrames 压缩
                    this._syncReadFrameToCPU(f);
                    this._pendingIdle.delete(f.id);
                }
            }

            // 清掉已经不需要备份的 shared 表项（处理过后仍挂在表里会无意义地延长排队）
            for (const [id, entry] of this._pendingIdle) {
                if (entry.type !== 'shared') continue;
                const f = this._history.find(fr => fr.id === id);
                if (!f || f.cpuReady) this._pendingIdle.delete(id);
            }

            // 压缩遗留的 cpuPixels 帧（例如 _readCanvasToCPU 保底路径产生的）
            this._maybeCompressOldFrames();

            // 如果还有待处理的，排下一次 idle
            const hasMore = this._history.some(f =>
                (f.gpuSlot && !f.cpuReady && !f._compressing) ||
                (f.cpuReady && f.cpuPixels && !f.cpuBlob && !f._compressing)
            );
            if (hasMore && !this._disposed) {
                this._scheduleIdleBackup(this._history[this._history.length - 1]);
            }
        };

        if (typeof requestIdleCallback !== 'undefined') {
            const handle = requestIdleCallback(doBackup, { timeout: IDLE_BACKUP_TIMEOUT_MS });
            this._pendingIdle.set(frame.id, { type: 'idle', handle });
        } else {
            const handle = setTimeout(doBackup, IDLE_BACKUP_FALLBACK_MS);
            this._pendingIdle.set(frame.id, { type: 'timeout', handle });
        }
    }

    _cancelIdleBackup(frame) {
        const entry = this._pendingIdle.get(frame.id);
        if (!entry) return;
        this._pendingIdle.delete(frame.id);

        if (entry.type === 'shared') return;
        // 真 handle 被取消：复位 flag，让下次 pushHistoryFrame 能重新挂 idle。
        // 如果当下还有 shared 表项在等（其他帧还需要备份），立刻补一次 schedule。
        if (entry.type === 'idle') cancelIdleCallback(entry.handle);
        else if (entry.type === 'timeout') clearTimeout(entry.handle);
        this._idleBackupScheduled = false;
        if (this._pendingIdle.size > 0 && this._history.length > 0 && !this._disposed) {
            this._scheduleIdleBackup(this._history[this._history.length - 1]);
        }
    }

    /**
     * 把一批被丢弃的帧"轻量部分"同步处理、重量部分异步分批处理：
     * - 同步：GPU slot 归还空闲池（必须立刻，否则新笔画会重分配显存导致峰值爆炸）
     *         + 取消 pending idle 备份记录
     * - 异步：解引用 cpuPixels / cpuBlob，清 _decompressCache，分批走 idle 降低单帧卡顿
     *
     * 场景触发：用户撤销 40+ 次后落新笔，一次性 splice 几十个 frame。
     */
    _scheduleAsyncRelease(frames) {
        // 同步把 GPU 资源和 idle 取消处理完（轻量、必要）
        for (const f of frames) {
            this._cancelIdleBackup(f);
            if (f.gpuSlot) {
                this._gpuFreeSlots.push(f.gpuSlot);
                f.gpuSlot = null;
            }
            if (this._decompressCache && this._decompressCache.has(f.id)) {
                this._decompressCache.delete(f.id);
            }
        }

        // cpuPixels / cpuBlob 的 Blob 解引用比较重（浏览器同步释放底层 buffer），
        // 推到 idle 分批做
        if (!this._releaseQueue) this._releaseQueue = [];
        for (const f of frames) this._releaseQueue.push(f);
        if (this._releaseScheduled) return;
        this._releaseScheduled = true;

        const BATCH = 8;
        const tick = () => {
            if (this._disposed) { this._releaseScheduled = false; return; }
            const n = Math.min(BATCH, this._releaseQueue.length);
            for (let i = 0; i < n; i++) {
                const f = this._releaseQueue.shift();
                f.cpuPixels = null;
                f.cpuReady  = false;
                f.cpuBlob   = null;
            }
            if (this._releaseQueue.length > 0) {
                if (typeof requestIdleCallback !== 'undefined') {
                    requestIdleCallback(tick, { timeout: 500 });
                } else {
                    setTimeout(tick, 0);
                }
            } else {
                this._releaseScheduled = false;
            }
        };
        if (typeof requestIdleCallback !== 'undefined') {
            requestIdleCallback(tick, { timeout: 500 });
        } else {
            setTimeout(tick, 0);
        }
    }

    _releaseFrame(frame) {
        this._cancelIdleBackup(frame);
        if (frame.gpuSlot) {
            this._gpuFreeSlots.push(frame.gpuSlot);
            frame.gpuSlot = null;
        }
        frame.cpuPixels = null;
        frame.cpuReady  = false;
        frame.cpuBlob   = null;
        if (this._decompressCache && this._decompressCache.has(frame.id)) {
            this._decompressCache.delete(frame.id);
        }
    }

    /**
     * 释放该 painter 持有的所有 GPU/CPU 资源。
     * 切换引擎或修改画布尺寸前调用，避免旧实例资源泄漏。
     * 调用后此实例不可再用。
     */
    dispose() {
        if (this._disposed) return;
        this._disposed = true;

        const gl = this.gl;
        if (!gl) return;

        // 停 RAF
        if (typeof this.stopHeatmapFadeOut === 'function') {
            try { this.stopHeatmapFadeOut(); } catch (_) {}
        }
        if (typeof this.stopHeatmapDecay === 'function') {
            try { this.stopHeatmapDecay(); } catch (_) {}
        }

        // 取消挂起的画布保存任务
        if (this._pendingSaveHandle !== undefined) {
            if (this._pendingSaveIsIdle) cancelIdleCallback(this._pendingSaveHandle);
            else clearTimeout(this._pendingSaveHandle);
            this._pendingSaveHandle = undefined;
        }

        // 终止压缩 Worker
        if (this._historyWorker) {
            try { this._historyWorker.terminate(); } catch (_) {}
            this._historyWorker = null;
        }
        if (this._workerPending) {
            for (const { reject } of this._workerPending.values()) {
                try { reject(new Error('disposed')); } catch (_) {}
            }
            this._workerPending.clear();
        }
        if (this._decompressCache) this._decompressCache.clear();

        // 释放队列里的 frame gpuSlot 已在 _scheduleAsyncRelease 同步阶段回收过，
        // 这里主动解除 cpuPixels/cpuBlob 引用，避免等 asyncRelease 的 idle tick
        // 醒来才释放（dispose 时那条 idle chain 的 handle 没存，无法显式 cancel）
        if (this._releaseQueue) {
            for (const f of this._releaseQueue) {
                f.cpuPixels = null;
                f.cpuReady  = false;
                f.cpuBlob   = null;
            }
            this._releaseQueue.length = 0;
        }

        // 销毁历史帧
        if (this._history) {
            for (const frame of this._history) {
                this._cancelIdleBackup(frame);
                if (frame.gpuSlot) {
                    gl.deleteTexture(frame.gpuSlot.tex);
                    gl.deleteFramebuffer(frame.gpuSlot.fb);
                    frame.gpuSlot = null;
                }
                frame.cpuPixels = null;
            }
            this._history.length = 0;
        }

        // 销毁空闲池
        if (this._gpuFreeSlots) {
            for (const slot of this._gpuFreeSlots) {
                gl.deleteTexture(slot.tex);
                gl.deleteFramebuffer(slot.fb);
            }
            this._gpuFreeSlots.length = 0;
        }

        // 销毁运行时纹理
        if (this.textures) {
            const seen = new Set();
            const external = this._externalTextures || null;
            for (const key in this.textures) {
                const tex = this.textures[key];
                if (tex && !seen.has(tex)) {
                    seen.add(tex);
                    // 外部管理的纹理（如 mixbox 模块级单例 LUT）不能 deleteTexture，
                    // 否则模块缓存里的纹理 ID 失效，下次同 gl 重建时会返回已删的纹理
                    if (external && external.has(tex)) continue;
                    gl.deleteTexture(tex);
                }
            }
            this.textures = {};
        }

        // 销毁 framebuffer
        if (this.framebuffers) {
            const seen = new Set();
            for (const key in this.framebuffers) {
                const fb = this.framebuffers[key];
                if (fb && !seen.has(fb)) {
                    seen.add(fb);
                    gl.deleteFramebuffer(fb);
                }
            }
            this.framebuffers = {};
        }
        if (this._copyReadFB) {
            gl.deleteFramebuffer(this._copyReadFB);
            this._copyReadFB = null;
        }

        // 销毁笔刷纹理
        if (this.currentBrushTexture) {
            gl.deleteTexture(this.currentBrushTexture);
            this.currentBrushTexture = null;
        }
        if (this._softBrushTexture) {
            gl.deleteTexture(this._softBrushTexture);
            this._softBrushTexture = null;
            this._softBrushTextureCanvas = null;
        }
        if (this._softBrushCanvasCache) this._softBrushCanvasCache.clear();
        this.lastBrushCanvas = null;

        // shader programs / VBO / locations 全部模块级缓存，dispose 不释放（整个会话复用）。
        // 只清引用，避免外部代码误用已废弃 painter 的 this.program 等字段。
        this.buffers = {};
        this._blitBuffer = null;
        this.program = null;
        this._blitProgram = null;
        this._heatmapProgram = null;
        this._heatDecayProgram = null;
        this._heatDecayBuf = null;
        this._wetSpreadProgram = null;
        this._wetSpreadBuf = null;
        this._wetColorProgram = null;
        this._wetColorBuf = null;
    }

    /**
     * 将 canvas 内容异步写入 localStorage
     * 不阻塞当前帧，toDataURL 在 idle 时执行
     * @param {Function} callback - 接收无参数，负责调用 paletteStorage.save()
     */
    scheduleIdleSave(callback) {
        // 只保留最新一次请求：前一次还没跑就取消，避免连续笔画时 PNG 编码 + localStorage 写入堆积
        if (this._pendingSaveHandle !== undefined) {
            if (this._pendingSaveIsIdle) cancelIdleCallback(this._pendingSaveHandle);
            else clearTimeout(this._pendingSaveHandle);
        }
        if (typeof requestIdleCallback !== 'undefined') {
            this._pendingSaveIsIdle = true;
            this._pendingSaveHandle = requestIdleCallback(() => {
                this._pendingSaveHandle = undefined;
                callback();
            }, { timeout: IDLE_SAVE_TIMEOUT_MS });
        } else {
            this._pendingSaveIsIdle = false;
            this._pendingSaveHandle = setTimeout(() => {
                this._pendingSaveHandle = undefined;
                callback();
            }, IDLE_SAVE_FALLBACK_MS);
        }
    }

    /**
     * 把当前画布内容导出为 dataURL（不读 WebGL canvas，避免触发浏览器合成闪烁）
     * 通过 readPixels → 离屏 2D canvas → toDataURL 实现
     */
    toDataURL(type = 'image/png', quality) {
        const cw = this.canvas.width;
        const ch = this.canvas.height;

        // 从离屏 framebuffer 读回并转成屏幕行序，不碰 default framebuffer。
        const flipped = this._readPixelsForStorage(this.framebuffers.canvas, cw, ch);

        // 用离屏 2D canvas 生成 dataURL，不触碰 WebGL canvas
        const offscreen = document.createElement('canvas');
        offscreen.width  = cw;
        offscreen.height = ch;
        offscreen.getContext('2d').putImageData(new ImageData(flipped, cw, ch), 0, 0);
        return quality !== undefined ? offscreen.toDataURL(type, quality) : offscreen.toDataURL(type);
    }

    /**
     * Async export: WebP at quality 1 reuses the history worker for encoding preparation.
     * Other formats and worker failures use the original main-thread canvas fallback.
     */
    async toDataURLAsync(type = 'image/webp', quality = 1.0) {
        const cw = this.canvas.width;
        const ch = this.canvas.height;

        const flipped = this._readPixelsForStorage(this.framebuffers.canvas, cw, ch);

        // convertToBlob can perform synchronous preparation before returning its Promise.
        let blob;
        // Match the history worker's existing WebP codec and quality exactly.
        // Clone rather than transfer: retain this snapshot for the fallback if the worker fails.
        if (type === 'image/webp' && quality === 1.0) {
            try {
                blob = await this._workerRequest({ type: 'compress', pixels: flipped.buffer, w: cw, h: ch });
            } catch (_) {}
        }
        if (!blob && typeof OffscreenCanvas !== 'undefined') {
            const oc = new OffscreenCanvas(cw, ch);
            oc.getContext('2d').putImageData(new ImageData(flipped, cw, ch), 0, 0);
            blob = await oc.convertToBlob({ type, quality });
        } else if (!blob) {
            // 回退路径
            const c = document.createElement('canvas');
            c.width = cw; c.height = ch;
            c.getContext('2d').putImageData(new ImageData(flipped, cw, ch), 0, 0);
            blob = await new Promise(r => c.toBlob(r, type, quality));
        }
        // blob → dataURL（FileReader 异步）
        return await new Promise((resolve, reject) => {
            const fr = new FileReader();
            fr.onload = () => resolve(fr.result);
            fr.onerror = () => reject(fr.error);
            fr.readAsDataURL(blob);
        });
    }

}

// 记录本脚本 URL，用于 Worker 等相对资源的绝对路径解析（避免子目录部署坏路径）
BaseWebGLPainter._scriptURL = (document.currentScript && document.currentScript.src) || '';

// ──────────────────────────────────────────────────────────────
// 模块级 shader/buffer 缓存：一次编译整个会话复用。
//   main：按子类构造器名分键（MB/KM 各一）
//   其余辅助 program 源码与引擎无关，全局共用一份。
// 缓存条目结构：{ program, locations, buffer? }。
// dispose 不得 deleteProgram/deleteBuffer 这些缓存项，否则下次拿到
// 失效的 WebGLProgram，drawArrays 会静默失败。
// ──────────────────────────────────────────────────────────────
BaseWebGLPainter._programCache = {
    main: new Map(),
    mainGeometry: null,
    blit:      null,
    heatmap:   null,
    heatDecay: null,
    wetSpread: null,
    wetColor:  null,
};

window.BaseWebGLPainter = BaseWebGLPainter;
console.log('BaseWebGLPainter 加载成功');


// ---------------------------------------------------------------- js/brush-manager.js
// ─── 水彩笔刷纹理参数 ─────────────────────────────────────────────────────────
const WC_DOT_COUNT      = 35;    // 点数
const WC_REF_SIZE       = 40;    // 基准笔尖：WC_DIST_RANGE 在此尺寸下成立，更大 size 时分布半径收紧
// 随机笔刷（watercolor/splatter/dry）变体池大小：每个 size 预生成 N 份，落笔随机挑一份
const RANDOM_VARIANT_COUNT = 4;
const WC_DIST_RANGE     = 0.8;   // 点分布半径（相对笔刷size）
const WC_DOT_SIZE_MIN   = 0.12;  // 点最小半径（相对size）
const WC_DOT_SIZE_RANGE = 0.18;  // 点大小随机范围
const WC_ALPHA_CENTER   = 0.5;   // 渐变中心 alpha
const WC_ALPHA_MID      = 0.3;   // 渐变中间 alpha（stop=0.5）
// ─────────────────────────────────────────────────────────────────────────────

/**
 * 笔刷管理器
 * 管理笔刷预览和笔刷生成
 */
class BrushManager {
    constructor() {
        // 预设笔刷
        this.presetBrushes = [
            { type: 'circle' },
            { type: 'soft' },
            { type: 'watercolor' },
            { type: 'splatter' },
            { type: 'flat' },
            { type: 'dry' }
        ];
        // 笔刷纹理缓存
        // 确定性笔刷（circle/soft/flat）：key = `${type}_${size}` → canvas
        // 随机笔刷（watercolor/splatter/dry）：key = `${type}_${size}` → canvas[]（变体池）
        this._brushCache = new Map();
        // 当前笔画使用的变体（refreshRandomBrush 写入，createBrushTexture 读取）
        // key = `${type}_${size}` → canvas
        this._activeVariant = new Map();
        // 上一次使用的变体索引；新一笔只在剩余变体中挑，避免连续两笔用同一份纹理
        // （不连续的"偶发重复"仍允许）
        // key = `${type}_${size}` → number
        this._lastVariantIdx = new Map();
        // 上次使用的变体索引，下笔从剩余变体里挑，避免连续两笔撞同一份纹理
        // key = `${type}_${size}` → number
        this._lastVariantIdx = new Map();
    }

    /**
     * 绘制笔刷预览
     */
    drawBrushPreview(ctx, x, y, size, type) {
        ctx.fillStyle = '#fff';
        
        switch(type) {
            case 'circle':
                ctx.beginPath();
                ctx.arc(x, y, size, 0, Math.PI * 2);
                ctx.fill();
                break;
                
            case 'soft':
                // 修复：显示正确的渐变圆形
                const gradient = ctx.createRadialGradient(x, y, 0, x, y, size);
                gradient.addColorStop(0, 'rgba(255, 255, 255, 1)');
                gradient.addColorStop(0.6, 'rgba(255, 255, 255, 0.4)');
                gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');
                ctx.fillStyle = gradient;
                ctx.beginPath();
                ctx.arc(x, y, size, 0, Math.PI * 2);
                ctx.fill();
                break;
                
            case 'watercolor':
                ctx.globalAlpha = 0.8;
                for (let i = 0; i < 20; i++) {
                    const angle = Math.random() * Math.PI * 2;
                    const dotSize = size * (0.1 + Math.random() * 0.2);
                    const maxDist = size * 0.9 - dotSize;
                    const dist = Math.random() * maxDist;
                    ctx.beginPath();
                    ctx.arc(x + Math.cos(angle) * dist, y + Math.sin(angle) * dist, dotSize, 0, Math.PI * 2);
                    ctx.fill();
                }
                ctx.globalAlpha = 1;
                break;
                
            case 'splatter':
                for (let i = 0; i < 14; i++) {
                    const angle = Math.random() * Math.PI * 2;
                    const dist = size * Math.pow(Math.random(), 0.7) * 0.82;
                    const proximity = 1 - dist / size;
                    const dotSize = size * (0.03 + proximity * 0.07 + Math.random() * 0.04);
                    const px = x + Math.cos(angle) * dist;
                    const py = y + Math.sin(angle) * dist;
                    const grad = ctx.createRadialGradient(px, py, dotSize * 0.5, px, py, dotSize);
                    grad.addColorStop(0, 'rgba(255,255,255,1)');
                    grad.addColorStop(1, 'rgba(255,255,255,0)');
                    ctx.fillStyle = grad;
                    ctx.beginPath();
                    ctx.arc(px, py, dotSize, 0, Math.PI * 2);
                    ctx.fill();
                }
                ctx.fillStyle = '#fff';
                break;
                
            case 'flat':
                // 修复：15° 倾斜角度
                ctx.save();
                ctx.translate(x, y);
                ctx.rotate(Math.PI / 12);  // 15° = π/12
                ctx.fillRect(-size * 1.2, -size * 0.4, size * 2.4, size * 0.8);
                ctx.restore();
                break;
                
            case 'dry':
                // 干笔刷 - 不规则边缘
                ctx.globalAlpha = 0.8;
                for (let i = 0; i < 20; i++) {
                    const angle = Math.random() * Math.PI * 2;
                    const dotSize = size * (0.1 + Math.random() * 0.2);
                    const maxDist = size * 0.9 - dotSize; // 确保点不超出画布边缘
                    const dist = Math.random() * maxDist;
                    ctx.beginPath();
                    ctx.arc(x + Math.cos(angle) * dist, y + Math.sin(angle) * dist, dotSize, 0, Math.PI * 2);
                    ctx.fill();
                }
                ctx.globalAlpha = 1;
                break;
        }
    }

    /**
     * 是否为含随机元素的笔刷（用变体池策略）
     */
    _isRandomBrush(brush) {
        return !brush.image && (brush.type === 'watercolor' || brush.type === 'splatter' || brush.type === 'dry');
    }

    /**
     * 落笔时调用：确保变体池存在（懒生成 RANDOM_VARIANT_COUNT 份），
     * 然后从池中随机挑一份作为本笔的"激活变体"，下次 createBrushTexture 直接返回它
     */
    refreshRandomBrush(size, brush) {
        if (!this._isRandomBrush(brush)) return;
        const key = `${brush.type}_${size}`;
        let pool = this._brushCache.get(key);
        if (!Array.isArray(pool)) {
            pool = [];
            for (let i = 0; i < RANDOM_VARIANT_COUNT; i++) {
                pool.push(this._buildBrushCanvas(size, brush));
            }
            this._brushCache.set(key, pool);
        }
        const lastIdx = this._lastVariantIdx.get(key);
        let idx = Math.floor(Math.random() * pool.length);
        if (idx === lastIdx && pool.length > 1) {
            // 连撞同一份：在剩余 N-1 份里再挑一次（>=2 份就保证与上一笔不同）
            idx = (idx + 1 + Math.floor(Math.random() * (pool.length - 1))) % pool.length;
        }
        this._lastVariantIdx.set(key, idx);
        this._activeVariant.set(key, pool[idx]);
    }

    /**
     * 创建笔刷纹理
     */
    createBrushTexture(size, brush) {
        const cacheable = !brush.image;
        if (cacheable) {
            const key = `${brush.type}_${size}`;
            if (this._isRandomBrush(brush)) {
                // 随机笔刷：返回当前激活变体；池未建则现场建一份并激活
                const active = this._activeVariant.get(key);
                if (active) return active;
                this.refreshRandomBrush(size, brush);
                return this._activeVariant.get(key);
            }
            // 确定性笔刷：单 canvas 缓存
            const cached = this._brushCache.get(key);
            if (cached) return cached;
        }
        const canvas = this._buildBrushCanvas(size, brush);
        if (cacheable) {
            this._brushCache.set(`${brush.type}_${size}`, canvas);
        }
        return canvas;
    }

    /**
     * 实际生成一份笔刷 canvas（不带任何缓存逻辑）
     */
    _buildBrushCanvas(size, brush) {

        const canvas = document.createElement('canvas');
        canvas.width = size * 2;
        canvas.height = size * 2;
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        ctx.clearRect(0, 0, size * 2, size * 2);

        const centerX = size;
        const centerY = size;

        if (brush.image) {
            // 自定义图片笔刷
            ctx.drawImage(brush.image, 0, 0, size * 2, size * 2);
        } else {
            // 预设笔刷（简化版，保留核心形状）
            // 填黑色：shader 只用 alpha 通道，黑色不会对混色产生白色偏移
            ctx.fillStyle = '#000';
            
            switch(brush.type) {
                case 'circle':
                    ctx.beginPath();
                    ctx.arc(centerX, centerY, size * 0.9, 0, Math.PI * 2);
                    ctx.fill();
                    break;
                    
                case 'soft':
                    const gradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, size);
                    gradient.addColorStop(0, 'rgba(255, 255, 255, 1)');
                    gradient.addColorStop(0.7, 'rgba(255, 255, 255, 0.5)');
                    gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');
                    ctx.fillStyle = gradient;
                    ctx.fillRect(0, 0, size * 2, size * 2);
                    break;
                    
                case 'watercolor': {
                    // 大尺寸下分布半径按 sqrt(REF/size) 收紧，让 35 个点之间的间距与 size=40 接近；
                    // 点本身仍按 size 等比放大。size ≤ REF 时 distScale=1，不影响小笔尖手感。
                    const distScale = size > WC_REF_SIZE ? Math.sqrt(WC_REF_SIZE / size) : 1;
                    for (let i = 0; i < WC_DOT_COUNT; i++) {
                        const angle = Math.random() * Math.PI * 2;
                        const dist = Math.sqrt(Math.random()) * size * WC_DIST_RANGE * distScale;
                        const dotSize = size * (WC_DOT_SIZE_MIN + Math.random() * WC_DOT_SIZE_RANGE);
                        const cx = centerX + Math.cos(angle) * dist;
                        const cy = centerY + Math.sin(angle) * dist;
                        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, dotSize);
                        grad.addColorStop(0,   `rgba(0,0,0,${WC_ALPHA_CENTER})`);
                        grad.addColorStop(0.5, `rgba(0,0,0,${WC_ALPHA_MID})`);
                        grad.addColorStop(1,   'rgba(0,0,0,0)');
                        ctx.fillStyle = grad;
                        ctx.beginPath();
                        ctx.arc(cx, cy, dotSize, 0, Math.PI * 2);
                        ctx.fill();
                    }
                    break;
                }
                    
                case 'splatter': {
                    // 第一步：在离屏 canvas 上画散落圆点
                    const dotCanvas = document.createElement('canvas');
                    dotCanvas.width = size * 2;
                    dotCanvas.height = size * 2;
                    const dotCtx = dotCanvas.getContext('2d');
                    const totalDots = 28;
                    for (let i = 0; i < totalDots; i++) {
                        const angle = Math.random() * Math.PI * 2;
                        // 幂次分布让点向中心聚集；限制在 0.82 以内确保不超出贴图
                        const dist = size * Math.pow(Math.random(), 0.7) * 0.82;
                        // 外围的点更小，增强中心密外围稀的视觉感
                        const proximity = 1 - dist / size;
                        const dotSize = size * (0.03 + proximity * 0.07 + Math.random() * 0.04);
                        const cx = centerX + Math.cos(angle) * dist;
                        const cy = centerY + Math.sin(angle) * dist;
                        // 每个点用径向渐变实现柔和边缘
                        const inner = Math.max(0, dotSize * 0.5);
                        const grad = dotCtx.createRadialGradient(cx, cy, inner, cx, cy, dotSize);
                        grad.addColorStop(0, 'rgba(0,0,0,1)');
                        grad.addColorStop(1, 'rgba(0,0,0,0)');
                        dotCtx.fillStyle = grad;
                        dotCtx.beginPath();
                        dotCtx.arc(cx, cy, dotSize, 0, Math.PI * 2);
                        dotCtx.fill();
                    }

                    // 第二步：用整体径向 envelope 压暗外缘，消除贴图轮廓感
                    // destination-in 让点层只保留 envelope 的 alpha 形状
                    const envGrad = dotCtx.createRadialGradient(centerX, centerY, 0, centerX, centerY, size * 0.9);
                    envGrad.addColorStop(0,    'rgba(0,0,0,0.55)');
                    envGrad.addColorStop(0.3,  'rgba(0,0,0,0.85)');
                    envGrad.addColorStop(0.55, 'rgba(0,0,0,1)');
                    envGrad.addColorStop(1,    'rgba(0,0,0,0)');
                    dotCtx.globalCompositeOperation = 'destination-in';
                    dotCtx.fillStyle = envGrad;
                    dotCtx.fillRect(0, 0, size * 2, size * 2);

                    // 第三步：把结果贴到主纹理
                    ctx.drawImage(dotCanvas, 0, 0);
                    ctx.fillStyle = '#000';
                    ctx.globalAlpha = 1;
                    break;
                }
                    
                case 'flat':
                    ctx.save();
                    ctx.translate(centerX, centerY);
                    ctx.rotate(Math.PI / 12);
                    ctx.fillRect(-size * 1.2, -size * 0.4, size * 2.4, size * 0.8);
                    ctx.restore();
                    break;
                    
                case 'dry':
                    ctx.globalAlpha = 0.8;
                    for (let i = 0; i < 60; i++) {
                        const angle = Math.random() * Math.PI * 2;
                        // 平方根分布让点向中心集中，减少中间空洞感
                        const dist = Math.sqrt(Math.random()) * size * 0.85;
                        const dotSize = size * (0.03 + Math.random() * 0.07);
                        ctx.beginPath();
                        ctx.arc(centerX + Math.cos(angle) * dist, centerY + Math.sin(angle) * dist, dotSize, 0, Math.PI * 2);
                        ctx.fill();
                    }
                    ctx.globalAlpha = 1;
                    break;
            }
        }
        
        return canvas;
    }

    /**
     * 获取预设笔刷列表
     */
    getPresetBrushes() {
        return this.presetBrushes;
    }
}

// ---------------------------------------------------------------- js/palette-storage.js
/**
 * 画布持久化存储类
 * 负责保存和加载画布状态、调色盘预设、笔刷设置和历史记录
 */
class PaletteStorage {
    constructor(key = 'mixbox_canvas_v1', paletteKey = 'mixbox_palette_preset', brushKey = 'mixbox_brush_settings', historyKey = 'mixbox_history', settingsKey = 'mixbox_app_settings') {
        this.key = key;
        this.paletteKey = paletteKey;
        this.brushKey = brushKey;
        this.historyKey = historyKey;
        this.settingsKey = settingsKey;
        this.autoSaveTimer = null;

        this.toolStateKeyPrefix = 'mb_tool_';
        this._toolStateTimers = {};
        this._toolStateDelay = 200;

        // appSettings 内存缓存 + debounce：避免滑条/颜色变动时每次都走
        // getItem+parse+merge+stringify+setItem 的同步 I/O 循环。
        this._appSettingsCache = null;     // null 表示尚未读取过
        this._appSettingsDirty = false;
        this._appSettingsTimer = null;
        this._appSettingsDelay = 300;
    }

    /**
     * 保存画布内容
     */
    save(canvasDataURL) {
        try {
            localStorage.setItem(this.key, canvasDataURL);
            console.log('💾 画布已自动保存');
            return true;
        } catch (e) {
            console.error('保存失败:', e);
            return false;
        }
    }

    /**
     * 加载画布内容
     */
    load() {
        try {
            const saved = localStorage.getItem(this.key);
            if (saved) {
                console.log('✅ 加载已保存的画布');
                return saved;
            }
        } catch (e) {
            console.error('加载失败:', e);
        }
        return null;
    }

    /**
     * 保存调色盘预设
     */
    savePalettePreset(presetName) {
        try {
            localStorage.setItem(this.paletteKey, presetName);
            return true;
        } catch (e) {
            console.error('调色盘预设保存失败:', e);
            return false;
        }
    }

    /**
     * 加载调色盘预设
     */
    loadPalettePreset() {
        try {
            const savedPreset = localStorage.getItem(this.paletteKey);
            if (savedPreset) return savedPreset;
        } catch (e) {
            console.error('调色盘预设加载失败:', e);
        }
        return null;
    }

    /**
     * 保存笔刷设置（旧接口，内部合并到 appSettings）
     */
    saveBrushSettings(settings) {
        try {
            localStorage.setItem(this.brushKey, JSON.stringify(settings));
            return true;
        } catch (e) {
            console.error('笔刷设置保存失败:', e);
            return false;
        }
    }

    /**
     * 加载笔刷设置
     */
    loadBrushSettings() {
        try {
            const savedSettings = localStorage.getItem(this.brushKey);
            if (savedSettings) {
                console.log('✅ 加载已保存的笔刷设置');
                return JSON.parse(savedSettings);
            }
        } catch (e) {
            console.error('笔刷设置加载失败:', e);
        }
        return null;
    }

    /**
     * 保存应用全局设置（颜色、混合强度等）
     * settings: { foregroundColor, backgroundColor, brushMixStrength,
     *             smudgeBrushSize, smudgeStrength }
     *
     * 改为内存缓存 + debounce 写入：滑条/颜色连续触发时只有最后一次真正落盘。
     * 页面关闭前通过 flushAppSettings() 同步 flush；beforeunload 钩子已接好。
     */
    saveAppSettings(settings) {
        // 首次访问时把磁盘内容灌进缓存
        if (this._appSettingsCache === null) {
            this._appSettingsCache = this._readAppSettingsFromDisk() || {};
        }
        Object.assign(this._appSettingsCache, settings);
        this._appSettingsDirty = true;
        if (this._appSettingsTimer) clearTimeout(this._appSettingsTimer);
        this._appSettingsTimer = setTimeout(() => this.flushAppSettings(), this._appSettingsDelay);
        return true;
    }

    /**
     * 强制把缓存中的 appSettings 同步写入 localStorage。
     * beforeunload / 切引擎 / resize 等关键节点调用。
     */
    flushAppSettings() {
        if (this._appSettingsTimer) {
            clearTimeout(this._appSettingsTimer);
            this._appSettingsTimer = null;
        }
        if (!this._appSettingsDirty || !this._appSettingsCache) return;
        try {
            localStorage.setItem(this.settingsKey, JSON.stringify(this._appSettingsCache));
            this._appSettingsDirty = false;
        } catch (e) {
            console.error('应用设置保存失败:', e);
        }
    }

    /**
     * 加载应用全局设置。命中缓存时直接返回，避免重复 parse。
     */
    loadAppSettings() {
        if (this._appSettingsCache !== null) return this._appSettingsCache;
        const disk = this._readAppSettingsFromDisk();
        this._appSettingsCache = disk || {};
        return disk;
    }

    _readAppSettingsFromDisk() {
        try {
            const saved = localStorage.getItem(this.settingsKey);
            if (saved) return JSON.parse(saved);
        } catch (e) {
            console.error('应用设置加载失败:', e);
        }
        return null;
    }

    /**
     * 保存历史记录
     */
    saveHistory(historyData, historyStep) {
        try {
            const data = JSON.stringify({ history: historyData, step: historyStep });
            localStorage.setItem(this.historyKey, data);
            return true;
        } catch (e) {
            console.error('历史记录保存失败:', e);
            return false;
        }
    }

    /**
     * 加载历史记录
     */
    loadHistory() {
        try {
            const saved = localStorage.getItem(this.historyKey);
            if (saved) {
                const data = JSON.parse(saved);
                console.log('✅ 加载已保存的历史记录');
                return data;
            }
        } catch (e) {
            console.error('历史记录加载失败:', e);
        }
        return null;
    }

    /**
     * 自动保存（防抖）
     */
    autoSave(canvasDataURL, delay = 2000) {
        clearTimeout(this.autoSaveTimer);
        this.autoSaveTimer = setTimeout(() => {
            this.save(canvasDataURL);
        }, delay);
    }

    /**
     * 保存全部数据（画布、调色盘预设和笔刷设置）
     */
    saveAll(canvasDataURL, palettePreset, brushSettings) {
        this.save(canvasDataURL);
        this.savePalettePreset(palettePreset);
        if (brushSettings) {
            this.saveBrushSettings(brushSettings);
        }
    }

    /**
     * 自动保存全部数据（防抖）
     */
    autoSaveAll(canvasDataURL, palettePreset, brushSettings, delay = 2000) {
        clearTimeout(this.autoSaveTimer);
        this.autoSaveTimer = setTimeout(() => {
            this.saveAll(canvasDataURL, palettePreset, brushSettings);
        }, delay);
    }

    /**
     * 加载某个工具/笔型的 state（toolStates 重构后用）
     * mode: 'brush' | 'watercolor' | 'smudge'
     */
    loadToolState(mode) {
        try {
            const raw = localStorage.getItem(this.toolStateKeyPrefix + mode);
            if (raw) return JSON.parse(raw);
        } catch (e) {
            console.error('toolState 加载失败:', mode, e);
        }
        return null;
    }

    saveToolState(mode, state) {
        // 先把待写入的快照存住，flushToolStates 时按这个写
        if (!this._pendingToolStates) this._pendingToolStates = {};
        this._pendingToolStates[mode] = JSON.parse(JSON.stringify(state));
        if (this._toolStateTimers[mode]) clearTimeout(this._toolStateTimers[mode]);
        this._toolStateTimers[mode] = setTimeout(() => {
            this._writeToolState(mode);
        }, this._toolStateDelay);
    }

    _writeToolState(mode) {
        if (!this._pendingToolStates || !(mode in this._pendingToolStates)) return;
        try {
            localStorage.setItem(this.toolStateKeyPrefix + mode, JSON.stringify(this._pendingToolStates[mode]));
        } catch (e) {
            console.error('toolState 保存失败:', mode, e);
        }
        delete this._pendingToolStates[mode];
        if (this._toolStateTimers[mode]) {
            clearTimeout(this._toolStateTimers[mode]);
            this._toolStateTimers[mode] = null;
        }
    }

    flushToolStates() {
        if (!this._pendingToolStates) return;
        for (const mode of Object.keys(this._pendingToolStates)) {
            this._writeToolState(mode);
        }
    }

    /**
     * 清除
     */
    clear() {
        localStorage.removeItem(this.key);
        console.log('🗑️ 画布已清除');
    }

    /**
     * 清除全部数据
     */
    clearAll() {
        localStorage.removeItem(this.key);
        localStorage.removeItem(this.paletteKey);
        localStorage.removeItem(this.brushKey);
        localStorage.removeItem(this.historyKey);
        localStorage.removeItem(this.settingsKey);
        ['brush', 'watercolor', 'smudge'].forEach(m => localStorage.removeItem(this.toolStateKeyPrefix + m));
        console.log('🗑️ 所有数据已清除');
    }
}


